INSERT INTO `Collection` (`id`, `name`, `slug`, `subtitle`, `description`, `heroImage`, `featured`, `status`, `createdAt`, `updatedAt`) VALUES ('cmtli9kax000a74oioeqxqb9t', 'The Nocturne Series', 'the-nocturne-series', 'Shadowed woods, velvety leathers & nocturnal roses', 'Conceived for the hours between midnight and dawn. A provocative collection dominated by dark agarwood, smoldering incense, and velvet florals.', 'https://images.unsplash.com/photo-1508746829417-e6f548d8d6ed?q=80&w=1400&auto=format&fit=crop', 1, 'ACTIVE', '2026-09-03 12:32:46', '2026-09-03 12:32:46');
INSERT INTO `Collection` (`id`, `name`, `slug`, `subtitle`, `description`, `heroImage`, `featured`, `status`, `createdAt`, `updatedAt`) VALUES ('cmtli9kb3000b74oiu11zj1vo', 'Private Reserve', 'private-reserve', 'Aged distillations & sacred botanicals', 'Extremely limited small-batch creations featuring vintage Mysore sandalwood, rare distillates, and barrel-aged amber resins.', 'https://images.unsplash.com/photo-1594035910387-fea47794261f?q=80&w=1400&auto=format&fit=crop', 1, 'ACTIVE', '2026-09-03 12:32:46', '2026-09-03 12:32:46');
INSERT INTO `Collection` (`id`, `name`, `slug`, `subtitle`, `description`, `heroImage`, `featured`, `status`, `createdAt`, `updatedAt`) VALUES ('cmtli9kb8000c74oivvu1m47h', 'L\'Or d\'Orient', 'lor-dorient', 'Molten ambers, Florentine iris & royal solar notes', 'A tribute to the golden route of antiquity. Luminous, sun-drenched resins and powdered iris bathed in warm antique gold aura.', 'https://images.unsplash.com/photo-1563178406-4cdc2923acbc?q=80&w=1400&auto=format&fit=crop', 1, 'ACTIVE', '2026-09-03 12:32:46', '2026-09-03 12:32:46');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kdn000t74oi9b1wq1vs', 'Oud Nocturne', 'oud-nocturne', 'FRG-EXT-001', 'Shadowed Cambodian Agarwood & Smoked Frankincense', 'An intense, enigmatic exploration of nocturnal elegance. Rare aged Cambodian oud intertwines with smoldering frankincense, velvety leather, and the intoxicating warmth of bourbon vanilla. Unfolds on the skin with sovereign distinction.', 340, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Saffron Suede","Calabrian Bergamot","Cracked Cardamom"]', '["Smoked Incense","Taif Rose Absolu","Florentine Iris Pallida"]', '["Cambodian Agarwood (Oud)","Bourbon Vanilla Bean","Tuscan Suede Accord"]', 'Smoldering Koh Kong agarwood, birch tar, bourbon vanilla, and raw oceanic ambergris.', '2026-09-03 12:32:46', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kex001d74oiqymm7fmj', 'Santal Impérial', 'santal-imperial', 'FRG-EXT-002', 'Sacred Mysore Sandalwood & Creamy Cashmeran', 'A masterwork of quiet majesty. Sacred Mysore sandalwood draped in crisp cardamom pods, white amber, and crystalline cedarwood. Silky, opulent, and whispering timeless authority.', 320, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 29, 'ACTIVE', 1, 0, 'cmtli9kb3000b74oiu11zj1vo', '["Cracked Cardamom","Calabrian Bergamot"]', '["Mysore Sandalwood","Florentine Iris Pallida"]', '["Bourbon Vanilla Bean","Tuscan Suede Accord"]', 'Ancient vintage Mysore sandalwood, atlas cedar, and cashmeran.', '2026-09-03 12:32:47', '2026-09-03 15:59:10');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kfk001o74oin6v2vyyo', 'Ambre Céleste', 'ambre-celeste', 'FRG-EXT-003', 'Golden Moroccan Labdanum & Royal Siam Benzoin', 'A radiant golden hour captured in obsidian glass. Golden labdanum resin melts over royal benzoin and dark honeycomb, infused with toasted coriander and warm almond blossoms.', 290, 260, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 1, 'cmtli9kb8000c74oivvu1m47h', '["Calabrian Bergamot","Cracked Cardamom"]', '["Moroccan Labdanum","Siam Benzoin"]', '["Bourbon Vanilla Bean","Cambodian Agarwood (Oud)"]', 'Golden labdanum resin, royal benzoin tears, and dark honeycomb.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kgc002174oi6u92h6m5', 'Rose Velours', 'rose-velours', 'FRG-EXT-004', 'Midnight Damask Rose, Suede & Black Pepper', 'A nocturnal velvet rose stripped of innocence. Crimson Damask petals dipped in black pepper, Turkish coffee, and dark Indonesian patchouli, settling into warm Tuscan suede.', 310, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Calabrian Bergamot","Cracked Cardamom"]', '["Taif Rose Absolu"]', '["Tuscan Suede Accord","Bourbon Vanilla Bean"]', 'Midnight crimson rose, dark patchouli, and Tuscan suede.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kgw002a74oib9gzvkkk', 'Cuir Tabac', 'cuir-tabac', 'FRG-EXT-005', 'Havana Blonde Leaf, Vintage Cognac & Smoked Cacao', 'The aroma of private members’ clubs and antique leather armchairs. Cured blonde tobacco leaves steeped in oak-barrel cognac, sweetened with dried prune and smoked Venezuelan cacao.', 350, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kb3000b74oiu11zj1vo', '["Cracked Cardamom"]', '["Blonde Tobacco Leaf"]', '["Tuscan Suede Accord","Smoked Incense"]', 'Aged blonde tobacco leaf, oak cognac barrel, and smoky styrax.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9khf002j74oirkgjgjrd', 'Iris d’Or', 'iris-dor', 'FRG-EXT-006', 'Florentine Pallida Iris Butter & White Cashmere', 'Three-year aged Florentine iris pallida butter. Powdery yet luminous, wrapped in sparkling champagne aldehydes, almond milk, and golden ambroxan. Pure couture perfumery.', 380, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 0, 1, 'cmtli9kb8000c74oivvu1m47h', '["Calabrian Bergamot"]', '["Florentine Iris Pallida"]', '["Bourbon Vanilla Bean"]', 'Three-year aged Florentine iris pallida butter and white cashmere.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9khs002p74oi9rb1ds0a', 'Vétiver Solaire', 'vetiver-solaire', 'FRG-EXT-007', 'Sun-Bleached Haitian Vetiver & Green Bergamot', 'Earth washed in radiant golden light. Smoky, mineral roots of Haitian vetiver sharpened by green bergamot zest and warm Mediterranean sun-salt.', 280, 245, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 0, 0, 'cmtli9kb3000b74oiu11zj1vo', '["Calabrian Bergamot"]', '["Haitian Vetiver Coeur"]', '["Smoked Incense"]', 'Haitian vetiver roots, mineral ambergris, and sun-salt.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9ki9002x74oittk5nuf7', 'Néroli Renaissance', 'neroli-renaissance', 'FRG-EXT-008', 'Tunisian Orange Blossom & Solar Amber Crystal', 'The architecture of a Mediterranean dawn. Dew-kissed Tunisian orange blossoms electrified with candied citron rind and anchored in deep crystalline amber.', 295, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 0, 0, 'cmtli9kb8000c74oivvu1m47h', '["Calabrian Bergamot"]', '["Tunisian Orange Blossom"]', '["Moroccan Labdanum"]', 'Orange blossom absolute, crystalline solar molecules, and milky sandalwood.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kim003374oi1rx6lc46', 'ABRAR', 'abrar', 'FRG-ABR-100', 'Royal Smoked Oud, Crimson Saffron & Bourbon Amber', 'Abrar is the pinnacle of the Maison\'s private creations. Wild Cambodian agarwood is distilled over thirty-year sandalwood shavings and enriched with saffron stigmas and vanilla bourbon.', 360, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 1, 'cmtli9kb8000c74oivvu1m47h', '["Kashmiri Saffron","Wild Bergamot","Cardamom Pods"]', '["Smoked Oud Royale","Damascena Rose","Nutmeg Essence"]', '["Bourbon Amber","Mysore Sandalwood","Black Leather"]', 'Smoked Cambodian Agarwood & Warm Bourbon Amber', '2026-09-03 12:32:47', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtli9kjb003e74oicpxiadpi', 'Solstice Privé', 'solstice-prive', 'FRG-EXT-010', 'Vintage 2021 Maceration & Taif Rose Absolu', 'An ultra-limited vintage distillation reserved exclusively for private patronage. All flacons from this harvest are currently claimed in our vault.', 450, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 0, 0, 'cmtli9kb3000b74oiu11zj1vo', '["Taif Rose Absolu","Pink Pepper"]', '["Cambodian Agarwood (Oud)","Smoked Incense"]', '["Mysore Sandalwood","Grey Ambergris"]', 'Aged Taif rose, smoked incense, and vintage grey ambergris.', '2026-09-03 12:32:47', '2026-09-03 15:58:52');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrshe00012gfq683t4ex5', 'AAMEE', 'aamee', 'FRG-AAM-100', 'Smoked Frankincense, Golden Amber & Dark Woods', 'Aamee is a tribute to the sacred incense rituals of the Levant. Sun-bleached Hojari frankincense tears are macerated with aged labdanum resin, black pepper, and cedarwood to create a meditative, sovereign sillage.', 340, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Hojari Frankincense","Pink Pepper","Elemi"]', '["Smoked Labdanum","Dark Myrrh","Nutmeg"]', '["Atlas Cedarwood","Golden Amber","Benzoin"]', 'Smoked Resins & Rich Golden Amber', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrshp00072gfq1wryrb1z', 'KISWAH', 'kiswah', 'FRG-KIS-100', 'Royal Black Musk, Velvet Taif Rose & Aged Agarwood', 'Kiswah embodies the grandeur of ceremonial silk cloaks steeped in century-old attars. Dark deer musk accord, morning-plucked Taif rose, and twenty-year-aged Cambodian agarwood weave a cloak of unmatched luxury.', 380, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Taif Rose Absolue","Bergamot","Saffron Threads"]', '["Royal Black Musk","Geranium Bourbon","Cardamom"]', '["Cambodian Agarwood","Indonesian Patchouli","Warm Amber"]', 'Nocturnal Black Musk & Ancient Agarwood', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrsi9000f2gfqyddeiok7', 'QALB', 'qalb', 'FRG-QLB-100', 'Noble Florentine Iris, Saffron & Cashmere Woods', 'Qalb—meaning "Heart"—is an intimate contemplation on Florentine orris root. Aged three years underground before cold steam distillation, its powdery violet facets are warmed by crimson saffron and cashmere musk.', 350, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Florentine Orris Butter","White Peach","Aldehydes"]', '["Kashmiri Saffron","Heliotrope","Violet Leaf"]', '["Cashmere Woods","White Amber","Clean Musk"]', 'Powdery Orris Butter & Soft Cashmere', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrsij000l2gfq7ioco24u', 'ALI', 'ali', 'FRG-ALI-100', 'Imperial Leather, Smoked Birch & Dark Ambergris', 'Ali is a commanding composition of masculine power and quiet nobility. Tuscan cuoio leather cured in smoked birch tar and softened by ambergris and wild coriander seed.', 340, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Coriander Seed","Bitter Orange","Juniper Berry"]', '["Tuscan Cuoio Leather","Black Pepper","Cistus"]', '["Smoked Birch Tar","Dark Ambergris","Haitian Vetiver"]', 'Imperial Cuoio Leather & Birch Tar', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrsit000r2gfqsrsebfty', 'LE CUIR', 'le-cuir', 'FRG-CUI-100', 'Vintage Parisian Saddle Leather, Violet & Vetiver', 'Le Cuir captures the atmosphere of a confidential Parisian book atelier. Aged cordovan leather, crushed violet leaves, and smoked vetiver roots dried over peat embers.', 320, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Violet Leaf Absolue","Thyme","Mandarin"]', '["Aged Saddle Leather","Smoked Iris","Nutmeg"]', '["Haitian Vetiver","Cedarwood","Styrax"]', 'Aged Cordovan Leather & Peat-Smoked Vetiver', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrsj3000x2gfq4wl0mfui', 'FOUGÈRE', 'fougere', 'FRG-FOU-100', 'High-Altitude Grasse Lavender, Oakmoss & Coumarin', 'A nocturnal reinvention of the quintessential French accord. Wild high-altitude lavender harvested at midnight, damp green oakmoss from the Vosges forest, and roasted tonka bean.', 295, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Grasse Lavender","Bergamot","Spearmint"]', '["Geranium Bourbon","Clary Sage","Black Pepper"]', '["French Oakmoss","Roasted Tonka Bean","White Cedar"]', 'Wild Alpine Lavender & Forest Oakmoss', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
INSERT INTO `Product` (`id`, `name`, `slug`, `sku`, `shortDescription`, `description`, `price`, `salePrice`, `currency`, `size`, `stockQuantity`, `status`, `featured`, `newArrival`, `collectionId`, `topNotes`, `heartNotes`, `baseNotes`, `baseDescription`, `createdAt`, `updatedAt`) VALUES ('cmtltrsje00132gfq8lcqe8ks', 'AWQAD', 'awqad', 'FRG-AWQ-100', 'Raw Cambodian Agarwood, Frankincense & Siam Benzoin', 'Awqad is an uncompromised celebration of wild agarwood. Pure, unblended vintage Cambodian oud resin is paired with Siam benzoin and amber crystals to produce a sillage that endures for days.', 390, NULL, 'USD', '100 ml / 3.4 FL. OZ.', 30, 'ACTIVE', 1, 0, 'cmtli9kax000a74oioeqxqb9t', '["Saffron Oil","Pimento Berry","Blood Orange"]', '["Cambodian Agarwood Oil","Rose Centifolia","Clove Bud"]', '["Siam Benzoin","Oman Frankincense","Castoreum Accord"]', 'Raw Wild Agarwood & Siam Benzoin Crystals', '2026-09-03 17:54:53', '2026-09-03 17:54:53');
